+import { db } from '../db';
+import { sendWebhook } from './send';
+
+/** Deliver every webhook that has not been delivered yet. */
+export async function dispatchPending(): Promise<number> {
+  const pending = await db.webhooks.findMany({ where: { delivered: false } });
+
+  for (const hook of pending) {
+    // Fire and forget: a slow endpoint must not stall the loop.
+    sendWebhook(hook);
+    await db.webhooks.update({ where: { id: hook.id }, data: { delivered: true } });
+  }
+
+  return pending.length;
+}
